  question: string;
  answer: string;
};

export default function HomePage() {
  const { tm } = getI18n();
  const tripleReviews = tm<LandingReview[]>("landing.reviews.triple") ?? [];
  const singleReview = tm<LandingReview>("landing.reviews.single");
  const gridReviews = tm<LandingReview[]>("landing.reviews.grid") ?? [];
  const featureItems = tm<LandingFeature[]>("landing.features.items") ?? [];
  const faqItems = tm<LandingFaq[]>("landing.faq.items") ?? [];
  const featureComponents = [
    (item: LandingFeature) => (
      <Image
        src="/images/placeholder1.gif"
        alt={item.title}
        width={200}
        height={100}
        className="h-auto w-full object-cover"
        unoptimized
      />
    ),
    (item: LandingFeature) => (
      <Image
        src="/images/placeholder1.gif"
        alt={item.title}
        width={200}
        height={100}
        className="h-auto w-full object-cover"
      />
    ),
    (item: LandingFeature) => (
      <Image
        src="/images/placeholder1.gif"
        alt={item.title}
        width={200}
        height={100}
        className="h-auto w-full object-cover"
        unoptimized
      />
    ),
    (item: LandingFeature) => (
      <Image
        src="/images/placeholder1.gif"
        alt={item.title}
        width={200}
        height={100}
        className="h-auto w-full object-cover"
        unoptimized
      />
    ),
  ];
  const featuresWithComponents = featureItems
    .map((item, index) => {
      const componentFn = featureComponents.at(index);
      if (componentFn === undefined) return null;
      return {
        ...item,
        component: componentFn(item),
      };
    })
    .filter((item): item is LandingFeatureWithComponent => item !== null);

  return (
    <div className="bg-background text-foreground relative flex h-fit flex-col">
      <div className="mt-16"></div>

      <LandingHeader />

      <Hero />

      <StatsSection />

      <BentoGridSection />

      <PainSection />

      <SectionDivider />

      <ReviewTriple reviews={tripleReviews.slice(0, 3)} />

      <SectionDivider />

      {singleReview && (
        <ReviewSingle
          image={singleReview.image}
          name={singleReview.name}
          review={singleReview.review}
          role={singleReview.role}
          compagnyImage={singleReview.compagnyImage}
        />
      )}

      <FeaturesSection features={featuresWithComponents} />

      <CTAImageSection />

      <CTASectionCard />

      <CtaSection />

      <Pricing />

      <FAQSection faq={faqItems} />

      <SectionDivider />

      <ReviewGrid reviews={gridReviews} />

      <EmailFormSection />

      <SectionDivider />

      <Footer />
    </div>
  );
}

